def assign_roles(apps, schema_editor):
    """Роль по истории: есть объявление и ни одного свайпа комнат — «Сдаю комнату», иначе «Ищу комнату».
    И включаем роли «только сотрудникам» для проверки."""
    Profile = apps.get_model("accounts", "Profile")
    Listing = apps.get_model("listings", "Listing")
    Swipe = apps.get_model("matching", "Swipe")
    FeatureFlag = apps.get_model("accounts", "FeatureFlag")

    owners = set(Listing.objects.values_list("owner_id", flat=True))
    seekers_swiped = set(Swipe.objects.filter(side="seeker").values_list("seeker_id", flat=True))
    for profile in Profile.objects.all().iterator():
        is_owner = profile.user_id in owners and profile.user_id not in seekers_swiped
        profile.role = "owner" if is_owner else "seeker"
        profile.save(update_fields=["role"])
    FeatureFlag.objects.get_or_create(key="roles", defaults={"mode": "staff"})


